func TreeLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Tree {
	return (*Tree)(tableRegionLoadRetain(region, wire, TreeTableType(), TreeTableType().NodeType, 2, report, retain))
}
func TreeMeasureRetain(value *Tree, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), TreeTableType(), nil, true, retain, nil, allocator...)
}
func TreeSaveRetain(value *Tree, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), TreeTableType(), buffer, false, retain, report, allocator...)
}
func TreeMeasureBodyRetain(value *Tree, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !TreeSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

