// MilestoneReset restores Milestone's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MilestoneReset(value *Milestone) {
	value.Number = 1
	value.Title = 0
}

func MilestoneMeasureBody(value *Milestone, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !MilestoneSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func MilestoneSaveBody(w *TableWriter, value *Milestone) bool {
	if !MilestoneSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func MilestoneSaveBodyFields(w *TableWriter, value *Milestone) bool {
	{
		if value.Number != 1 {
			if ref := w.Ids.refAtHit(36, 0x8031a80d73f6ebe0); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			if value.Number < 1 || value.Number > 2147483648 {
				return false
			}
			w.Put64(uint64(value.Number))
		}
	}
	{
		if value.Title != 0 {
			if ref := w.Ids.refAtHit(68, 0xda31296c0c1b6029); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Title == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Title)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

