func LinkedPRReadStrict(wire []byte) (*LinkedPR, error) {
	var b LinkedPRBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := LinkedPRLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type LinkedPRBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *LinkedPRBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(LinkedPR{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LinkedPRReset((*LinkedPR)(p))
	return true
}
func (b *LinkedPRBuilder) GetRoot() *LinkedPR {
	if b.Arena.Locked {
		return nil
	}
	return (*LinkedPR)(b.Arena.At(b.root))
}
func (b *LinkedPRBuilder) AsConst() *LinkedPR {
	if len(b.region) == 0 {
		return nil
	}
	return (*LinkedPR)(unsafe.Pointer(&b.region[0]))
}
func (b *LinkedPRBuilder) Region() []byte { return b.region }
func (b *LinkedPRBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), LinkedPRTableType(), &b.Arena)
}
func (b *LinkedPRBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), LinkedPRTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *LinkedPRBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), LinkedPRTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *LinkedPRBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// CountsReset restores Counts's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func CountsReset(value *Counts) {
	value.Repos = 0
	value.Issues = 0
	value.Comments = 0
	value.References = 0
	value.LinkedPrs = 0
}

func CountsMeasureBody(value *Counts, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Repos != 0 {
		bytes += tableLebBytes(ids.refAtHit(76, 0xf5400bf2b1f1d68a)) + 1 + 8
	} // repos
	if value.Issues != 0 {
		bytes += tableLebBytes(ids.refAtHit(34, 0x7c1b38ad2e75dc09)) + 1 + 8
	} // issues
	if value.Comments != 0 {
		bytes += tableLebBytes(ids.refAtHit(8, 0x2ce5b7abe8cec6d7)) + 1 + 8
	} // comments
	if value.References != 0 {
		bytes += tableLebBytes(ids.refAtHit(7, 0x26d68e9da3011d4b)) + 1 + 8
	} // references
	if value.LinkedPrs != 0 {
		bytes += tableLebBytes(ids.refAtHit(23, 0x56ee7333a6d63714)) + 1 + 8
	} // linked_prs
	if ids.Overflow {
		return -1
	}
	return bytes
}

func CountsMeasure(value *Counts) int64 {
	var ids TableIds
	body := CountsMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

